"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["11135"],{66181(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_distribuicao_vagas.modalidades_vazias","status":422,"titulo":"A oferta deve ter ao menos uma modalidade selecionada"},"descricao":{"codigo":"uniplus.selecao.configuracao_distribuicao_vagas.modalidades_vazias","requisitos":["UNI-REQ-0134"],"oQueAconteceu":["Uma das distribui\xe7\xf5es de vagas do corpo do pedido n\xe3o declarou nenhuma modalidade em\\n`modalidadeIds`. Diferente da lista de etapas do processo \u2014 onde uma lista\\nvazia \xe9 um estado v\xe1lido \u2014, uma distribui\xe7\xe3o de vagas sem nenhuma modalidade\\nn\xe3o tem sentido: \xe9 a modalidade que recebe a vaga distribu\xedda, sem nenhuma\\nn\xe3o h\xe1 o que distribuir.","Esta confer\xeancia conta os **Ids brutos** informados no corpo do pedido, antes de\\nresolver qualquer um deles contra o cat\xe1logo de modalidades \u2014 por isso roda\\nna mesma primeira passada de\\n[`vagas_ofertadas_base_invalido`](/erros/uniplus.selecao.configuracao_distribuicao_vagas.vagas_ofertadas_base_invalido)\\ne\\n[`percentual_da_reserva_legal_fora_do_limite`](/erros/uniplus.selecao.configuracao_distribuicao_vagas.percentual_da_reserva_legal_fora_do_limite),\\nacumulando com as duas \u2014 ver aquela p\xe1gina para o mecanismo completo. Sem\\nessa contagem bruta nesta primeira passada, um corpo do pedido com `modalidadeIds`\\nvazio **e** uma oferta de curso inexistente devolveria o erro de cat\xe1logo em\\nvez deste, mesmo a confer\xeancia de forma n\xe3o precisando de nenhum I/O para\\nconcluir que a lista est\xe1 vazia.","No corpo de erro, o campo desta viola\xe7\xe3o aparece como `distribuicaoVagas[<\xedndice>].modalidadeIds`, o nome usado no corpo do pedido."],"comoResolver":["Informe ao menos um `modalidadeId` em `modalidadeIds` para cada distribui\xe7\xe3o\\nde vagas do corpo do pedido. Se a resposta trouxer mais de uma viola\xe7\xe3o no array\\n`errors[]`, corrija todas antes de reenviar."],"ondeAparece":["Defini\xe7\xe3o de distribui\xe7\xe3o de vagas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao distribuicao vagas"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);